import { IconButton } from '@rocket.chat/fuselage';
import * as UiKit from '@rocket.chat/ui-kit';
import type { MouseEventHandler } from 'react';

import { useUiKitState } from '../hooks/useUiKitState';
import type { BlockProps } from '../utils/BlockProps';

export type IconButtonElementProps = BlockProps<UiKit.IconButtonElement>;

const IconButtonElement = ({ block, context }: IconButtonElementProps) => {
	const [{ loading }, action] = useUiKitState(block, context);

	const { url, value, label, icon } = block;
	const { icon: iconName, variant } = icon;

	const handleClick: MouseEventHandler = (e) => {
		void action({ target: e.currentTarget });
	};

	if (url && UiKit.isSafeUrl(url)) {
		return (
			<IconButton size='small' is='a' target='_blank' disabled={loading} icon={iconName} href={url} onClick={handleClick} title={label} />
		);
	}

	return (
		<IconButton
			icon={iconName}
			color={variant === 'default' ? 'default' : 'danger'}
			size='small'
			title={label}
			disabled={loading}
			value={value}
			onClick={handleClick}
		/>
	);
};

export default IconButtonElement;
